{
  "items": [
    {
      "name": "Real.pow_div_factorial_le_exp",
      "module_name": "Mathlib.Analysis.Complex.Exponential",
      "kind": "theorem",
      "type": "∀ (x : ℝ), 0 ≤ x → ∀ (n : ℕ), x ^ n / ↑n.factorial ≤ Real.exp x"
    },
    {
      "name": "Nat.eventually_pow_lt_factorial_sub",
      "module_name": "Mathlib.Order.Filter.AtTopBot.Finite",
      "kind": "theorem",
      "type": "∀ (c d : ℕ), ∀ᶠ (n : ℕ) in Filter.atTop, c ^ n < (n - d).factorial"
    },
    {
      "name": "Nat.factorization_factorial",
      "module_name": "Mathlib.Data.Nat.Choose.Factorization",
      "kind": "theorem",
      "type": "∀ {p : ℕ}, Nat.Prime p → ∀ {n b : ℕ}, Nat.log p n < b → n.factorial.factorization p = ∑ i ∈ Finset.Ico 1 b, n / p ^ i"
    },
    {
      "name": "Nat.Prime.emultiplicity_factorial",
      "module_name": "Mathlib.Data.Nat.Multiplicity",
      "kind": "theorem",
      "type": "∀ {p : ℕ}, Nat.Prime p → ∀ {n b : ℕ}, Nat.log p n < b → emultiplicity p n.factorial = ↑(∑ i ∈ Finset.Ico 1 b, n / p ^ i)"
    },
    {
      "name": "isLittleO_exp_mul_rpow_of_lt",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Asymptotics",
      "kind": "theorem",
      "type": "∀ (k : ℝ) {a b : ℝ}, a < b → (fun t => Real.exp (a * t) * t ^ k) =o[Filter.atTop] fun t => Real.exp (b * t)"
    }
  ]
}
